fn main(){let args=std::env::args().collect::<Vec<_>>();let contours:Vec<Vec<[f64;2]>>=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let spans=ingetrazo_render::qt_gray::rasterize(&contours,1_000_000,1_000_000).unwrap();let rows=spans.iter().map(|s|[s.x as i64,s.y as i64,s.len as i64,s.coverage as i64]).collect::<Vec<_>>();std::fs::write(&args[2],serde_json::to_vec(&rows).unwrap()).unwrap();}
